import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { createSubjectHandler } from "../handlers/createSubjectHandler";
import type { ApiError } from "../runtime/client";
import type { CreateSubjectRequest } from "../types/CreateSubjectRequest";

type Data = Awaited<ReturnType<typeof createSubjectHandler>>;
type Vars = CreateSubjectRequest;

export function useCreateSubject(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => createSubjectHandler(vars),
    ...options,
  });
}
